function formatSeconds(total: number) {
  const minutes = Math.floor(total / 60).toString().padStart(2, "0");
  const seconds = (total % 60).toString().padStart(2, "0");
  return `${minutes}:${seconds}`;
}

function CalendarPanel({ events }: { events: Array<{ id: number; startsAt: Date; title: string }> }) {
  const now = new Date(); const year = now.getFullYear(); const month = now.getMonth(); const first = new Date(year, month, 1); const daysInMonth = new Date(year, month + 1, 0).getDate(); const leading = (first.getDay() + 6) % 7; const slotCount = Math.ceil((leading + daysInMonth) / 7) * 7; const weekdays = ["月", "火", "水", "木", "金", "土", "日"];
  const eventDays = new Set(events.filter(event => { const date = new Date(event.startsAt); return date.getFullYear() === year && date.getMonth() === month; }).map(event => new Date(event.startsAt).getDate()));
  return <section className="glass-card overflow-hidden rounded-[28px] p-4"><div className="mb-3"><p className="eyebrow">learning calendar</p><h2 className="mt-1 text-lg font-bold">{year}年 {month + 1}月</h2><p className="mt-1 text-xs text-slate-400">保存済みの予定だけを表示します。</p></div><div className="grid grid-cols-7 gap-y-1 text-center text-[10px] text-slate-400">{weekdays.map(day => <span key={day}>{day}</span>)}</div><div className="mt-1 grid grid-cols-7 gap-1">{Array.from({ length: slotCount }, (_, index) => { const day = index - leading + 1; const current = day === now.getDate(); const hasEvent = eventDays.has(day); return <span key={index} className={`relative mx-auto grid h-8 w-8 place-items-center rounded-full text-xs ${day < 1 || day > daysInMonth ? "text-transparent" : current ? "bg-cyan-300 font-bold text-slate-950 shadow-[0_0_22px_rgba(109,232,221,.45)]" : hasEvent ? "bg-white/10 text-slate-50" : "text-slate-500"}`}>{day >= 1 && day <= daysInMonth ? day : ""}{hasEvent && !current && <i className="absolute bottom-1 h-1 w-1 rounded-full bg-cyan-300" />}</span>; })}</div><div className="mt-4 rounded-2xl bg-slate-950/30 px-3 py-3 text-xs text-slate-300">{events.length ? `今後の予定 ${events.length}件` : "登録済みの予定はありません。"}</div></section>;
}

