function QrScannerModal({ onDetected, onClose }: { onDetected: (value: string) => void; onClose: () => void }) {
  const videoRef = useRef<HTMLVideoElement>(null); const [message,setMessage]=useState("カメラを起動しています…");
  useEffect(()=>{let stream:MediaStream|undefined;let timer:number|undefined;let closed=false;const boot=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw new Error("CAMERA_UNAVAILABLE");stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});if(closed){stream.getTracks().forEach(track=>track.stop());return;}if(videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play();}const Detector=(window as Window & { BarcodeDetector?: new (options:{formats:string[]})=>{detect:(source:unknown)=>Promise<Array<{rawValue?:string}>>} }).BarcodeDetector;if(!Detector){setMessage("このブラウザはQRの自動読取に対応していません。教室コードを手入力してください。");return;}const detector=new Detector({formats:["qr_code"]});setMessage("QRコードを枠内に写してください。");timer=window.setInterval(async()=>{if(!videoRef.current)return;try{const found=await detector.detect(videoRef.current);const raw=found[0]?.rawValue?.trim();if(raw){const code=raw.replace(/^STUDYVERSE:/i,"").trim();onDetected(code);}}catch{/* フレーム読取失敗時は次の周期で再試行 */}},450);}catch(error){setMessage(error instanceof DOMException&&error.name==="NotAllowedError"?"カメラの利用が許可されませんでした。教室コードを手入力してください。":"カメラを開始できませんでした。教室コードを手入力してください。");}};void boot();return()=>{closed=true;if(timer)window.clearInterval(timer);stream?.getTracks().forEach(track=>track.stop());};},[onDetected]);
  return <div className="fixed inset-0 z-50 grid place-items-end bg-slate-950/80 p-4 sm:place-items-center"><section className="glass-card w-full max-w-md rounded-[28px] p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">qr classroom code</p><h2 className="mt-1 text-lg font-bold">教室コードを読み取る</h2></div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl bg-white/8" aria-label="閉じる"><X className="h-4 w-4"/></button></div><div className="mt-5 overflow-hidden rounded-2xl border border-cyan-200/20 bg-slate-950/45"><video ref={videoRef} muted playsInline className="aspect-video w-full object-cover"/><div className="relative -mt-[55%] mx-auto h-40 w-40 rounded-2xl border-2 border-cyan-200/80 shadow-[0_0_0_9999px_rgba(2,6,23,.2)]"/></div><p className="mt-5 text-center text-xs leading-5 text-slate-300">{message}</p><button onClick={onClose} className="mt-4 w-full rounded-xl border border-white/12 py-3 text-sm font-bold text-slate-200">手入力に戻る</button></section></div>;
}

function AdminBootstrap({ onClose }: { onClose: () => void }) {
  const auth=trpc.siteAdmin.me.useQuery(); const login=trpc.siteAdmin.login.useMutation(); const createRoom=trpc.classroom.rooms.create.useMutation(); const createOwner=trpc.classroom.members.createPinAccount.useMutation(); const utils=trpc.useUtils(); const [password,setPassword]=useState(""); const [name,setName]=useState(""); const [code,setCode]=useState(""); const [owner,setOwner]=useState(""); const [pin,setPin]=useState("");
  const signIn=async(event:React.FormEvent)=>{event.preventDefault();try{await login.mutateAsync({password});setPassword("");await utils.siteAdmin.me.invalidate();toast.success("全体管理者として認証しました。");}catch(error){toast.error(error instanceof Error?error.message:"認証できませんでした。");}};
  const submit=async(event:React.FormEvent)=>{event.preventDefault();if(!/^[A-Z0-9-]{3,32}$/.test(code.trim().toUpperCase()))return toast.error("教室コードは英数字とハイフンで3〜32文字にしてください。");if(!/^[0-9]{4}$/.test(pin))return toast.error("オーナーPINは4桁の数字で入力してください。");try{const room=await createRoom.mutateAsync({name:name.trim(),code:code.trim().toUpperCase()});if(!room.id)throw new Error("教室を作成できませんでした。");await createOwner.mutateAsync({classroomId:room.id,displayName:owner.trim(),pin,classroomRole:"owner"});toast.success("教室とオーナーPINを作成しました。PINは安全な場所で管理してください。");onClose();}catch(error){toast.error(error instanceof Error?error.message:"初期設定を保存できませんでした。");}};
  if(auth.isLoading)return <Modal title="管理者の初期設定" onClose={onClose}><p className="py-6 text-sm text-slate-300">管理者情報を確認しています…</p></Modal>;
  if(auth.data?.role!=="admin")return <Modal title="全体管理者ログイン" onClose={onClose}><p className="mt-4 text-sm leading-6 text-slate-300">このサイト固有の全体管理者パスワードを入力してください。外部アカウントとの連携は不要です。</p><form onSubmit={signIn}><label className="mt-5 block text-xs font-bold text-slate-200">全体管理者パスワード<input autoFocus required type="password" value={password} onChange={event=>setPassword(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="パスワードを入力"/></label><button disabled={login.isPending} className="mt-4 w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{login.isPending?"認証しています…":"全体管理者として認証"}</button></form></Modal>;
  return <Modal title="教室とオーナーPINを作成" onClose={onClose}><form onSubmit={submit} className="mt-4 space-y-3"><label className="block text-xs font-bold text-slate-200">教室名<input required value={name} onChange={event=>setName(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="例：東南学習教室"/></label><label className="block text-xs font-bold text-slate-200">教室コード<input required value={code} onChange={event=>setCode(event.target.value.toUpperCase())} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="例：STAR-2026"/></label><label className="block text-xs font-bold text-slate-200">オーナー表示名<input required value={owner} onChange={event=>setOwner(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="例：教室管理者"/></label><label className="block text-xs font-bold text-slate-200">オーナーPIN<input required inputMode="numeric" maxLength={4} value={pin} onChange={event=>setPin(event.target.value.replace(/\D/g,""))} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-center font-mono text-lg tracking-[.4em]" placeholder="••••"/></label><p className="text-[10px] leading-4 text-slate-400">PINは保存後に表示できません。作成直後に安全な経路で管理者へ共有してください。</p><button disabled={createRoom.isPending||createOwner.isPending} className="w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{createRoom.isPending||createOwner.isPending?"作成しています…":"教室とPINを作成"}</button></form></Modal>;
}

function TeacherAdminLogin({ onClose, onAuthenticated }: { onClose: () => void; onAuthenticated: (teacher: { id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string }) => void }) {
  const login = trpc.teacherAdmin.login.useMutation();
  const utils = trpc.useUtils();
  const [teacherId, setTeacherId] = useState("");
  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    const id = Number(teacherId);
    if (!Number.isInteger(id) || id <= 0) return toast.error("先生IDは正の整数で入力してください。");
    try {
      const result = await login.mutateAsync({ teacherId: id });
      await utils.teacherAdmin.me.invalidate();
      onAuthenticated(result.teacher);
      toast.success(`${result.teacher.classroomName}の先生管理画面を開きました。`);
      onClose();
    } catch (error) { toast.error(error instanceof Error ? error.message : "先生IDを確認できませんでした。"); }
  };
  return <Modal title="先生IDで管理画面へ" onClose={onClose}><p className="mt-3 text-sm leading-6 text-slate-300">全体管理者とは別に、担当教室に設定された先生IDでログインします。表示・操作できる内容は担当教室だけに限定されます。</p><form onSubmit={submit}><label className="mt-5 block text-xs font-bold text-slate-200">先生ID<input autoFocus required inputMode="numeric" value={teacherId} onChange={event => setTeacherId(event.target.value.replace(/\D/g, ""))} placeholder="例：1111" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" /></label><button disabled={login.isPending} className="mt-4 w-full rounded-xl bg-violet-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{login.isPending ? "認証しています…" : "先生管理画面を開く"}</button></form></Modal>;
}

function ClassroomMembersPanel() {
  const members = trpc.classroom.members.list.useQuery(undefined, { retry: false, staleTime: 20_000 });
  if (members.isLoading) return <section className="glass-card rounded-[24px] p-4"><p className="text-xs text-slate-400">利用者を読み込んでいます…</p></section>;
  if (members.isError) return <section className="rounded-[24px] border border-red-200/20 bg-red-400/5 p-4" role="alert"><p className="text-sm font-bold text-red-100">利用者を取得できませんでした</p><button onClick={() => void members.refetch()} className="mt-3 rounded-xl border border-red-200/30 px-3 py-2 text-xs font-bold text-red-100">再試行</button></section>;
  const rows = members.data ?? [];
  return <section className="glass-card rounded-[24px] p-4"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-cyan-300/12 text-cyan-100"><UserRound className="h-5 w-5" /></div><div><p className="text-sm font-bold">利用者</p><p className="mt-1 text-xs leading-5 text-slate-400">PINと教室コードで初回ログインした学習者は、登録操作なしでこの一覧へ自動追加されます。</p></div></div><div className="mt-4 space-y-2">{rows.length ? rows.map(member => <div key={member.id} className="flex items-center gap-3 rounded-xl bg-slate-950/30 p-3"><div className="grid h-8 w-8 place-items-center rounded-lg bg-cyan-300/12 text-xs font-bold text-cyan-100">{(member.displayName ?? "学").slice(0, 1)}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{member.displayName ?? `学習者 #${member.id}`}</p><p className="mt-1 text-[10px] text-slate-400">参加：{new Date(member.createdAt).toLocaleString("ja-JP")}</p></div><span className="rounded-full bg-white/8 px-2 py-1 text-[10px] text-slate-300">学習者</span></div>) : <p className="rounded-xl bg-slate-950/30 p-3 text-xs text-slate-400">まだ利用者はいません。最初のPINログイン後に自動で表示されます。</p>}</div></section>;
}

function LoginGate({ onEnter, onTeacherEnter }: { onEnter: (pin: string, classroom: string) => Promise<void>; onTeacherEnter: (teacher: { id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string }) => void }) {
  const [pin, setPin] = useState("");
  const [classroom, setClassroom] = useState("");
  const [showHelp, setShowHelp] = useState(false);
  const [scanning,setScanning]=useState(() => new URLSearchParams(window.location.search).get("preview") === "qr"); const [submitting,setSubmitting]=useState(false); const [adminSetup,setAdminSetup]=useState(() => new URLSearchParams(window.location.search).get("preview") === "admin-setup"); const [teacherLogin,setTeacherLogin]=useState(false);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); if (!isValidPin(pin)) return toast.error("PINは4桁の数字で入力してください。"); if (!isValidClassroomCode(classroom)) return toast.error("教室コードは英数字とハイフンで3〜32文字にしてください。");setSubmitting(true);try{await onEnter(pin, normalizeClassroomCode(classroom));}finally{setSubmitting(false);} };
  return <main className="sky-shell relative grid min-h-screen place-items-center overflow-hidden px-5 py-10"><div className="star-field" /><div className="absolute -left-24 top-8 h-64 w-64 rounded-full bg-cyan-300/10 blur-3xl" /><motion.section initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: .45 }} className="glass-card relative w-full max-w-[430px] rounded-[32px] p-6 sm:p-8">
    <div className="mb-8 flex items-center justify-between"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-gradient-to-br from-cyan-200 to-violet-400 text-slate-950 shadow-[0_0_25px_rgba(122,232,226,.35)]"><Sparkles className="h-5 w-5" /></div><div><p className="text-xl font-extrabold tracking-[-.04em]">StudyVerse</p><p className="font-mono text-[10px] uppercase tracking-[.18em] text-cyan-200">learning orbit</p></div></div><MoonStar className="h-5 w-5 text-slate-400" /></div>
    <div><p className="eyebrow">entry portal</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-.05em]">学びを、続ける軌道へ。</h1><p className="mt-3 text-sm leading-6 text-slate-300">4桁PINと教室コードで、あなたの学習空間を開きます。</p></div>
    <form onSubmit={submit} className="mt-7 space-y-5"><label className="block"><span className="mb-2 block text-xs font-semibold text-slate-200">4桁 PIN</span><div className="relative"><KeyRound className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-cyan-200" /><input autoFocus inputMode="numeric" maxLength={4} value={pin} onChange={e => setPin(e.target.value.replace(/\D/g, ""))} placeholder="• • • •" className="w-full rounded-2xl border border-white/12 bg-slate-950/35 py-3.5 pl-11 pr-4 text-center font-mono text-xl tracking-[.45em] text-white placeholder:tracking-[.3em] placeholder:text-slate-600" /></div></label>
      <label className="block"><span className="mb-2 block text-xs font-semibold text-slate-200">教室コード</span><div className="relative"><GraduationCap className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-violet-200" /><input value={classroom} onChange={e => setClassroom(e.target.value.toUpperCase())} placeholder="例：STAR-2026" className="w-full rounded-2xl border border-white/12 bg-slate-950/35 py-3.5 pl-11 pr-12 text-sm text-white placeholder:text-slate-500" /><button type="button" aria-label="教室コードを読み取る" onClick={() => setScanning(true)} className="absolute right-2 top-1/2 grid h-9 w-9 -translate-y-1/2 place-items-center rounded-xl text-cyan-200 transition hover:bg-white/10"><ScanLine className="h-5 w-5" /></button></div></label>
      <button disabled={submitting} type="submit" className="glow-pulse w-full rounded-2xl bg-gradient-to-r from-cyan-300 via-teal-200 to-cyan-300 py-4 text-sm font-extrabold text-slate-950 transition hover:brightness-110 active:scale-[.98] disabled:opacity-60">{submitting?"認証しています…":"学習空間をひらく"} <ArrowRight className="ml-1 inline h-4 w-4" /></button></form>
    <button onClick={() => setShowHelp(!showHelp)} className="mt-5 w-full text-center text-xs text-slate-400 underline-offset-4 hover:text-cyan-200 hover:underline">教室コードが分からない場合</button>{showHelp && <p className="mt-3 rounded-xl bg-white/6 p-3 text-xs leading-5 text-slate-300">先生から共有された教室コードを確認してください。コードがない場合は、先生または管理者に発行を依頼してください。</p>}<button onClick={()=>setTeacherLogin(true)} className="mt-3 w-full text-center text-xs font-bold text-cyan-200 hover:underline">先生IDで管理画面を開く</button><button onClick={()=>setAdminSetup(true)} className="mt-3 w-full text-center text-xs font-bold text-violet-200 hover:underline">全体管理者の初期設定</button>
    <p className="mt-8 text-center font-mono text-[9px] leading-4 tracking-wide text-slate-500">PINは4桁の数字のみを受け付けます。<br />同じPINでも教室が異なれば別の学習空間として扱います。</p>{scanning&&<QrScannerModal onClose={()=>setScanning(false)} onDetected={value=>{if(!/^[A-Za-z0-9-]{3,32}$/.test(value)){toast.error("QRコード内の教室コード形式が正しくありません。");return;}setClassroom(value.toUpperCase());setScanning(false);toast.success("教室コードを読み取りました。");}}/>}{teacherLogin&&<TeacherAdminLogin onClose={()=>setTeacherLogin(false)} onAuthenticated={onTeacherEnter}/>}{adminSetup&&<AdminBootstrap onClose={()=>setAdminSetup(false)}/>}
  </motion.section></main>;
}

function Header({ page, onBack, onProfile }: { page: string; onBack: () => void; onProfile: () => void }) {
  return <header className="sticky top-0 z-30 border-b border-white/[.06] bg-[#080f25]/80 px-4 py-3 backdrop-blur-xl"><div className="mx-auto flex max-w-5xl items-center justify-between"><div className="flex items-center gap-2"><button onClick={onBack} className="grid h-9 w-9 place-items-center rounded-xl border border-white/10 bg-white/5 text-slate-300 transition hover:bg-white/10" aria-label="前の画面に戻る"><ArrowLeft className="h-4 w-4" /></button><div><p className="text-sm font-extrabold tracking-[-.04em]">{page}</p><p className="font-mono text-[9px] tracking-[.16em] text-cyan-200">STUDYVERSE</p></div></div><div className="flex items-center gap-2"><button className="relative grid h-9 w-9 place-items-center rounded-xl border border-white/10 bg-white/5 text-slate-300 transition hover:bg-white/10" aria-label="通知"><Bell className="h-4 w-4" /><i className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-cyan-300" /></button><button onClick={onProfile} className="grid h-9 w-9 place-items-center rounded-xl bg-gradient-to-br from-violet-300 to-cyan-200 text-slate-950" aria-label="プロフィールを開く"><UserRound className="h-4 w-4" /></button></div></div></header>;
}

function TimerCard({ running, elapsed, onToggle, onReset }: { running: boolean; elapsed: number; onToggle: () => void; onReset: () => void }) {
  const duration = 25 * 60; const percentage = Math.min(elapsed / duration, 1) * 100;
  return <section className="glass-card rounded-[26px] p-4"><div className="flex items-start justify-between"><div><p className="eyebrow">focus timer</p><h2 className="mt-1 text-lg font-bold">集中モード</h2></div><span className="rounded-full bg-violet-300/13 px-2.5 py-1 font-mono text-[10px] text-violet-100">25 / 05</span></div><div className="mt-4 flex items-center gap-4"><div className="relative grid h-20 w-20 place-items-center rounded-full" style={{ background: `conic-gradient(#78ebe1 ${percentage}%, rgba(255,255,255,.09) 0)` }}><div className="grid h-[66px] w-[66px] place-items-center rounded-full bg-[#111d3c]"><span className="font-mono text-sm font-bold">{formatSeconds(Math.max(duration - elapsed, 0))}</span></div></div><div className="flex-1"><p className="text-sm font-semibold">25分、ひとつだけに集中。</p><p className="mt-1 text-xs leading-5 text-slate-400">タイマーは画面を移動しても時刻基準で続きます。</p><div className="mt-3 flex gap-2"><button onClick={onToggle} className="rounded-xl bg-cyan-300 px-3 py-2 text-xs font-bold text-slate-950 active:scale-[.97]">{running ? <><Pause className="mr-1 inline h-3.5 w-3.5" />一時停止</> : <><Play className="mr-1 inline h-3.5 w-3.5" />開始</>}</button><button onClick={onReset} className="rounded-xl border border-white/12 px-3 py-2 text-xs text-slate-200 transition hover:bg-white/8"><TimerReset className="mr-1 inline h-3.5 w-3.5" />リセット</button></div></div></div></section>;
}

function HomeView({ setPage, running, elapsed, onToggleTimer, onResetTimer, summary }: { setPage: (page: NavKey) => void; running: boolean; elapsed: number; onToggleTimer: () => void; onResetTimer: () => void; summary?: { totalFocusSeconds: number; retention: number; streak: number; records: number } }) {
  const [panel, setPanel] = useState(0); const totalMinutes=Math.floor((summary?.totalFocusSeconds??0)/60); const totalHours=Math.floor(totalMinutes/60); const remainingMinutes=totalMinutes%60; const calendar = trpc.classroom.calendar.list.useQuery(undefined, { retry: false, staleTime: 30_000 }); const review = trpc.learning.review.useQuery(undefined, { retry: false, staleTime: 30_000 });
  const panels = [<CalendarPanel key="calendar" events={calendar.data ?? []} />, <MonsterPanel key="monster" onEvolve={() => toast.info("進化にはあと6時間24分の学習時間が必要です。")}/>, <MissionPanel key="mission" onClaim={() => toast.success("受取可能な報酬を確認しました。")}/>];
  return <div className="space-y-4 px-4 pb-28 pt-5"><section className="relative overflow-hidden rounded-[28px] border border-cyan-100/10 bg-gradient-to-br from-[#173b61] via-[#18395b] to-[#18284f] p-5 shadow-[0_20px_55px_rgba(4,10,28,.35)]"><div className="soft-grid absolute inset-0 opacity-40" /><div className="relative"><div className="flex items-start justify-between"><div><p className="eyebrow text-cyan-100">your learning orbit</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-.06em]">StudyVerse</h1><p className="mt-1 text-xs text-slate-200">今日の小さな前進を、未来の力に。</p></div><div className="orb-float grid h-11 w-11 place-items-center rounded-2xl bg-cyan-200/16 text-cyan-100"><Sparkles className="h-5 w-5" /></div></div><div className="mt-6 grid grid-cols-3 divide-x divide-white/10"><div><p className="font-mono text-[10px] text-slate-300">TOTAL</p><p className="mt-1 text-lg font-bold">{totalHours}<span className="ml-1 text-xs font-medium text-slate-300">h {remainingMinutes}m</span></p></div><div className="pl-3"><p className="font-mono text-[10px] text-slate-300">RETAIN</p><p className="mt-1 text-lg font-bold">{summary?.retention??0}<span className="ml-1 text-xs font-medium text-slate-300">%</span></p></div><div className="pl-3"><p className="font-mono text-[10px] text-slate-300">STREAK</p><p className="mt-1 text-lg font-bold">{summary?.streak??0}<span className="ml-1 text-xs font-medium text-slate-300">days</span></p></div></div></div></section>
    <LearningTrendChart />
    <section><div className="mb-2 flex items-center justify-between"><div><p className="eyebrow">orbit panels</p><h2 className="mt-1 text-lg font-bold">学習の現在地</h2></div><div className="flex gap-1.5">{[0,1,2].map(i => <button key={i} aria-label={`パネル${i+1}`} onClick={() => setPanel(i)} className={`h-1.5 rounded-full transition-all ${i===panel ? "w-6 bg-cyan-200" : "w-1.5 bg-white/20"}`} />)}</div></div><AnimatePresence mode="wait"><motion.div key={panel} drag="x" dragConstraints={{ left: 0, right: 0 }} dragElastic={.12} onDragEnd={(_, info) => { if (info.offset.x > 45) setPanel(Math.max(0, panel - 1)); if (info.offset.x < -45) setPanel(Math.min(2, panel + 1)); }} initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -16 }} transition={{ duration: .18 }}>{panels[panel]}</motion.div></AnimatePresence><div className="mt-2 flex justify-between px-2"><button onClick={() => setPanel(Math.max(0,panel-1))} disabled={panel===0} className="text-xs text-slate-400 disabled:opacity-30"><ChevronLeft className="mr-1 inline h-4 w-4" />前へ</button><button onClick={() => setPanel(Math.min(2,panel+1))} disabled={panel===2} className="text-xs text-slate-400 disabled:opacity-30">次へ<ArrowRight className="ml-1 inline h-4 w-4" /></button></div></section>
    <TimerCard running={running} elapsed={elapsed} onToggle={onToggleTimer} onReset={onResetTimer}/>
    <section className="grid gap-3 sm:grid-cols-2"><button onClick={() => setPage("journal")} className="glass-card group rounded-[25px] p-4 text-left transition hover:-translate-y-0.5 hover:border-cyan-200/30"><NotebookPen className="h-5 w-5 text-cyan-200" /><p className="mt-4 text-base font-bold">StudyJournal</p><p className="mt-1 text-xs leading-5 text-slate-400">ニュースから、今日の読解をつくる。</p><span className="mt-3 inline-block text-xs font-bold text-cyan-200 group-hover:translate-x-1 transition-transform">記事を選ぶ <ArrowRight className="inline h-3.5 w-3.5" /></span></button><button onClick={() => { setPage("cards"); toast.info("AIセレクト10の練習・テストを選べます。"); }} className="glass-card group rounded-[25px] p-4 text-left transition hover:-translate-y-0.5 hover:border-violet-200/30"><BrainCircuit className="h-5 w-5 text-violet-200" /><p className="mt-4 text-base font-bold">AI セレクト 10</p><p className="mt-1 text-xs leading-5 text-slate-400">教室の教材から、今日の10問。</p><span className="mt-3 inline-block text-xs font-bold text-violet-200 group-hover:translate-x-1 transition-transform">英語・漢字を選ぶ <ArrowRight className="inline h-3.5 w-3.5" /></span></button></section>
    {(review.data ?? []).length > 0 && <section className="glass-card rounded-[25px] p-4"><div className="flex gap-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-amber-300/12 text-amber-200"><Bell className="h-4 w-4" /></div><div><p className="text-sm font-bold">復習する単語があります</p><p className="mt-1 text-xs leading-5 text-slate-400">単語カードで最後に間違えた {(review.data ?? []).length}語だけを復習できます。</p><button onClick={() => setPage("cards")} className="mt-2 text-xs font-bold text-cyan-200">復習をひらく <ArrowRight className="inline h-3.5 w-3.5" /></button></div></div></section>}
  </div>;
}

function BooksView({ books, setBooks, setPage }: { books: Record<Subject, Book[]>; setBooks: React.Dispatch<React.SetStateAction<Record<Subject, Book[]>>>; setPage: (page: NavKey) => void }) {
  const [subject, setSubject] = useState<Subject>("英単語"); const [selected, setSelected] = useState<Book | null>(null); const [creating, setCreating] = useState(false); const [title, setTitle] = useState("");
  const utils=trpc.useUtils(); const savedBooks=trpc.wordbooks.list.useQuery({subject:subject==="英単語"?"english":"kanji"},{retry:false}); const createRemote=trpc.wordbooks.create.useMutation();
  const library:Book[] = savedBooks.data ? savedBooks.data.map((book,index)=>({id:String(book.id),remoteId:book.id,name:book.title,count:book.wordCount,scope:book.visibility==="classroom"?"教室公開":book.visibility==="global"?"全体公開":"自分の教材",tone:index%2?"from-violet-400 to-indigo-500":"from-cyan-400 to-blue-500",words:book.words.map(word=>({id:word.id,front:word.front,back:word.back,reading:word.reading??undefined}))})) : books[subject];
  const createBook = async () => { if (!title.trim()) return toast.error("単語帳名を入力してください。"); try { await createRemote.mutateAsync({title:title.trim(),subject:subject==="英単語"?"english":"kanji",visibility:"private"}); await utils.wordbooks.list.invalidate(); setTitle("");setCreating(false);toast.success("単語帳を保存しました。"); } catch(error) { toast.error(error instanceof Error?error.message:"単語帳を保存できませんでした。"); } };
  return <div className="space-y-4 px-4 pb-28 pt-5"><section className="glass-card rounded-[26px] p-4"><p className="eyebrow">wordbook library</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">単語帳</h1><p className="mt-2 text-xs leading-5 text-slate-400">自分の教材と、教室で公開された教材を整理します。</p><div className="mt-5 grid grid-cols-2 rounded-xl bg-slate-950/35 p-1">{(["英単語","漢字"] as Subject[]).map(item => <button key={item} onClick={() => setSubject(item)} className={`rounded-lg py-2.5 text-sm font-bold transition ${item===subject ? "bg-white text-slate-950 shadow" : "text-slate-400"}`}>{item}</button>)}</div></section>
    <div className="flex items-center justify-between"><h2 className="text-sm font-bold">{subject}の単語帳 <span className="ml-1 font-mono text-xs font-normal text-slate-500">{library.length}冊</span></h2><button onClick={() => setCreating(true)} className="rounded-xl bg-cyan-300 px-3 py-2 text-xs font-bold text-slate-950"><Plus className="mr-1 inline h-3.5 w-3.5" />新規作成</button></div>
    <div className="space-y-2.5">{savedBooks.isLoading?<p className="text-xs text-slate-400">単語帳を読み込んでいます…</p>:library.length?library.map((book,index) => <button onClick={() => setSelected(book)} key={book.id} className="glass-card flex w-full items-center gap-3 rounded-[22px] p-3 text-left transition hover:border-cyan-100/30"><div className={`grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-gradient-to-br ${book.tone} text-slate-950`}><BookOpen className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="truncate text-sm font-bold">{book.name}</p>{index===0 && <span className="rounded-full bg-cyan-300/12 px-1.5 py-0.5 text-[9px] font-bold text-cyan-200">PINNED</span>}</div><p className="mt-1 text-xs text-slate-400">{book.count}語・{book.scope}</p></div><ChevronDown className="h-4 w-4 -rotate-90 text-slate-500" /></button>):<p className="rounded-2xl border border-dashed border-white/15 bg-white/[.025] p-4 text-xs leading-5 text-slate-400">まだ単語帳がありません。右上の「新規作成」から、保存する単語帳を作成してください。</p>}</div>
    {creating && <Modal title="マイ単語帳を作成" onClose={() => setCreating(false)}><p className="text-sm text-slate-300">{subject}用の単語帳名を入力してください。作成後、単語の追加とCSV取込が利用できます。</p><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="例：夏休みの復習" className="mt-4 w-full rounded-xl border border-white/12 bg-slate-950/40 px-3 py-3 text-sm" /><button disabled={createRemote.isPending} onClick={()=>void createBook()} className="mt-4 w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{createRemote.isPending?"保存しています…":"作成する"}</button></Modal>}
    {selected && <BookDetail book={selected} subject={subject} setBooks={setBooks} onPractice={() => { setSelected(null); setPage("cards"); }} onClose={() => setSelected(null)} />}
  </div>;
}

function Modal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-50 grid place-items-end bg-slate-950/70 p-4 sm:place-items-center"><motion.section initial={{ opacity:0, y:20 }} animate={{ opacity:1,y:0 }} className="glass-card w-full max-w-md rounded-[28px] p-5"><div className="flex items-center justify-between"><h2 className="text-lg font-bold">{title}</h2><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl bg-white/8"><X className="h-4 w-4" /></button></div>{children}</motion.section></div> }

function BookDetail({ book, subject, setBooks, onPractice, onClose }: { book: Book; subject: Subject; setBooks: React.Dispatch<React.SetStateAction<Record<Subject, Book[]>>>; onPractice: () => void; onClose: () => void }) {
  const [front,setFront]=useState(""); const [back,setBack]=useState(""); const [query,setQuery]=useState(""); const [editing,setEditing]=useState<number | null>(null);
  const utils=trpc.useUtils(); const addWord=trpc.wordbooks.addWord.useMutation(); const updateWord=trpc.wordbooks.updateWord.useMutation(); const deleteWord=trpc.wordbooks.deleteWord.useMutation();
  const refresh = async () => { await utils.wordbooks.list.invalidate(); };
  const save = async () => { if (!front.trim() || !back.trim()) return toast.error("表面と裏面を入力してください。"); try { if(book.remoteId){ const current=editing===null?undefined:book.words[editing]; if(current?.id) await updateWord.mutateAsync({vocabularyWordId:current.id,front:front.trim(),back:back.trim()}); else await addWord.mutateAsync({wordbookId:book.remoteId,front:front.trim(),back:back.trim(),source:"manual"}); await refresh(); toast.success(editing===null?"単語を保存しました。":"単語を更新しました。"); }else{ setBooks(current => ({...current, [subject]: current[subject].map(item => { if(item.id!==book.id)return item; const words=saveStudyWord(item.words,{front:front.trim(),back:back.trim()},editing); return {...item,words,count:words.length}; })})); toast.success(editing===null?"単語を追加しました。":"単語を更新しました。"); } setFront("");setBack("");setEditing(null); } catch(error) { toast.error(error instanceof Error?error.message:"単語を保存できませんでした。"); } };
  const edit=(word:Word,index:number)=>{setFront(word.front);setBack(word.back);setEditing(index);}; const remove=async(index:number)=>{try{const word=book.words[index];if(book.remoteId&&word?.id){await deleteWord.mutateAsync({vocabularyWordId:word.id});await refresh();}else setBooks(current=>({...current,[subject]:current[subject].map(item=>item.id===book.id?{...item,words:deleteStudyWord(item.words,index),count:Math.max(0,item.count-1)}:item)}));toast.success("単語を削除しました。");}catch(error){toast.error(error instanceof Error?error.message:"単語を削除できませんでした。");}};
  const filtered=searchStudyWords(book.words,query); const pending=addWord.isPending||updateWord.isPending||deleteWord.isPending;
  return <Modal title={book.name} onClose={onClose}><p className="text-xs text-slate-400">{book.scope}・{book.words.length}語を表示</p><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="単語を検索" className="mt-3 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-2.5 text-sm"/><div className="mt-3 max-h-44 space-y-2 overflow-y-auto pr-1">{filtered.length ? filtered.map(({word,index})=><div key={`${word.id??word.front}-${index}`} className="flex items-center gap-2 rounded-xl bg-slate-950/30 px-3 py-2.5"><span className="min-w-0 flex-1 truncate text-sm font-semibold">{word.front}</span><span className="max-w-[35%] truncate text-sm text-slate-300">{word.back}</span>{subject === "英単語" && <button onClick={() => window.speechSynthesis?.speak(new SpeechSynthesisUtterance(word.front))} className="text-cyan-200"><Volume2 className="h-4 w-4" /></button>}<button onClick={()=>edit(word,index)} disabled={pending} aria-label="単語を編集" className="text-violet-200 disabled:opacity-50"><Settings2 className="h-3.5 w-3.5" /></button><button onClick={()=>void remove(index)} disabled={pending} aria-label="単語を削除" className="text-red-200 disabled:opacity-50"><X className="h-3.5 w-3.5" /></button></div>) : <p className="rounded-xl bg-white/5 p-3 text-xs text-slate-400">一致する単語がありません。</p>}</div><div className="mt-4 grid grid-cols-2 gap-2"><input value={front} onChange={e=>setFront(e.target.value)} placeholder={subject==="英単語"?"英単語":"漢字"} className="rounded-xl border border-white/12 bg-slate-950/35 px-3 py-2.5 text-sm"/><input value={back} onChange={e=>setBack(e.target.value)} placeholder={subject==="英単語"?"意味":"読み"} className="rounded-xl border border-white/12 bg-slate-950/35 px-3 py-2.5 text-sm"/></div><button disabled={pending} onClick={()=>void save()} className="mt-2 w-full rounded-xl border border-cyan-200/25 py-2.5 text-xs font-bold text-cyan-200 disabled:opacity-60">{pending?"保存しています…":editing===null?"単語を追加":"単語を更新"}</button>{editing!==null&&<button onClick={()=>{setEditing(null);setFront("");setBack("");}} className="mt-2 w-full text-xs text-slate-400">編集を取り消す</button>}{book.remoteId?<CsvWordImporter wordbookId={book.remoteId} onComplete={async()=>{await refresh();onClose();}}/>:<p className="mt-4 rounded-xl bg-white/5 p-3 text-xs leading-5 text-slate-400">CSV取込は、保存済みの単語帳で利用できます。</p>}<button onClick={onPractice} className="mt-3 w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950">この単語帳で練習する <ArrowRight className="inline h-4 w-4" /></button></Modal>;
}

export function KanjiCanvasTest({ word, index, total, onAdvance, onExit, isSaving }: { word: Word; index: number; total: number; onAdvance: (correct: boolean) => Promise<void>; onExit: () => void; isSaving: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement>(null); const paths = useRef<{ x: number; y: number }[][]>([]); const activePath = useRef<{ x: number; y: number }[] | null>(null); const [checked,setChecked]=useState(false); const [,render]=useState(0);
  const point = (event: React.PointerEvent<HTMLCanvasElement>) => { const rect=event.currentTarget.getBoundingClientRect(); return {x:(event.clientX-rect.left)*(event.currentTarget.width/rect.width),y:(event.clientY-rect.top)*(event.currentTarget.height/rect.height)}; };
  const redraw = () => { const canvas=canvasRef.current; if(!canvas)return; const context=canvas.getContext("2d");if(!context)return;context.clearRect(0,0,canvas.width,canvas.height);context.strokeStyle="#092344";context.lineWidth=7;context.lineCap="round";context.lineJoin="round";paths.current.forEach(path=>{context.beginPath();path.forEach((item,i)=>i?context.lineTo(item.x,item.y):context.moveTo(item.x,item.y));context.stroke();}); };
  const start=(event:React.PointerEvent<HTMLCanvasElement>)=>{event.currentTarget.setPointerCapture(event.pointerId);activePath.current=[point(event)];paths.current.push(activePath.current);redraw();};
  const move=(event:React.PointerEvent<HTMLCanvasElement>)=>{if(!activePath.current)return;activePath.current.push(point(event));redraw();};
  const finish=()=>{if(activePath.current?.length===1){activePath.current.push({...activePath.current[0],x:activePath.current[0].x+1});redraw();}activePath.current=null;render(value=>value+1);};
  const undo=()=>{paths.current.pop();redraw();render(value=>value+1);}; const clear=()=>{paths.current=[];redraw();render(value=>value+1);};
  return <div className="px-4 pb-28 pt-5"><div className="mb-4 flex items-center justify-between"><div><p className="eyebrow">kanji test · {index+1} / {total}</p><p className="mt-1 text-sm text-slate-300">読みから漢字を書いて回答</p></div><button onClick={onExit} disabled={isSaving} className="text-xs text-slate-400 disabled:opacity-50">終了する</button></div><section className="glass-card rounded-[30px] p-5"><p className="text-xs text-slate-400">次の読みの漢字を書いてください</p><h1 className="mt-6 text-center text-4xl font-extrabold tracking-[.2em]">{word.back}</h1><div className="mt-7 overflow-hidden rounded-2xl bg-white p-2"><canvas ref={canvasRef} width={620} height={330} onPointerDown={start} onPointerMove={move} onPointerUp={finish} onPointerCancel={finish} className="h-52 w-full touch-none select-none rounded-xl bg-[linear-gradient(rgba(56,106,156,.13)_1px,transparent_1px),linear-gradient(90deg,rgba(56,106,156,.13)_1px,transparent_1px)] bg-[size:32px_32px]" aria-label="漢字を書いて回答するキャンバス" /></div><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={undo} disabled={isSaving} className="rounded-xl border border-white/14 py-2.5 text-xs font-bold text-slate-200 disabled:opacity-50"><RotateCcw className="mr-1 inline h-3.5 w-3.5" />一画前に戻る</button><button onClick={clear} disabled={isSaving} className="rounded-xl border border-white/14 py-2.5 text-xs font-bold text-slate-200 disabled:opacity-50">全消去</button></div>{!checked?<button onClick={()=>setChecked(true)} disabled={isSaving} className="mt-3 w-full rounded-xl bg-cyan-300 py-3.5 text-sm font-bold text-slate-950 disabled:opacity-60">答えを確認する</button>:<div className="mt-4 rounded-2xl bg-cyan-300/10 p-3"><p className="text-xs text-cyan-100">正解の漢字</p><p className="mt-1 text-2xl font-extrabold text-white">{word.front}</p><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={()=>void onAdvance(false)} disabled={isSaving} className="rounded-xl border border-violet-200/25 py-2.5 text-xs font-bold text-violet-100 disabled:opacity-50">{isSaving?"保存中…":"書き直す"}</button><button onClick={()=>void onAdvance(true)} disabled={isSaving} className="rounded-xl bg-cyan-300 py-2.5 text-xs font-bold text-slate-950 disabled:opacity-60">{isSaving?"保存中…":"次の問題"}</button></div></div>}</section></div>;
}

export function CardsView({ books }: { books: Record<Subject, Book[]> }) {
  const [mode, setMode] = useState<"choose"|"practice"|"test"|"result">("choose"); const [subject,setSubject]=useState<Subject>("英単語"); const [index,setIndex]=useState(0); const [flipped,setFlipped]=useState(false); const [result,setResult]=useState({known:0,review:0}); const [answer,setAnswer]=useState(""); const [isSaving,setIsSaving]=useState(false); const savingRef=useRef(false);
  const recordAnswer=trpc.learning.recordAnswer.useMutation();
  const words=useMemo(() => books[subject].flatMap(book=>book.words).slice(0,5),[books,subject]); const word=words[index] ?? {front:"準備中",back:"単語帳に単語を追加してください"};
  const choose = (next: "practice"|"test") => { if(!words.length) return toast.error("先に単語帳へ単語を追加してください。"); setMode(next); setIndex(0);setFlipped(false);setResult({known:0,review:0});setAnswer(""); };
  const advance = async (known:boolean) => { if(savingRef.current)return; savingRef.current=true;setIsSaving(true);const recordMode=mode==="practice"?"practice":"test";try{const updated=await saveAnswerAndGetProgress(()=>recordAnswer.mutateAsync({mode:recordMode,isCorrect:known}),index,words.length,known,result.known,result.review);setResult({known:updated.known,review:updated.review});if(updated.completed){setMode("result");toast.success("学習記録を保存しました。");}else{setIndex(updated.nextIndex);setFlipped(false);setAnswer("");}}catch(error){toast.error(error instanceof Error?error.message:"回答記録を保存できませんでした。通信状況を確認して再試行してください。");}finally{savingRef.current=false;setIsSaving(false);}};
  if(mode==="choose") return <div className="space-y-4 px-4 pb-28 pt-5"><section className="glass-card rounded-[26px] p-5"><p className="eyebrow">recall station</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">単語カード</h1><p className="mt-2 text-xs leading-5 text-slate-400">カードをめくり、覚えた感覚を記録します。テストは回答後に結果を表示します。</p><div className="mt-5 grid grid-cols-2 rounded-xl bg-slate-950/35 p-1">{(["英単語","漢字"] as Subject[]).map(item=><button key={item} onClick={()=>setSubject(item)} className={`rounded-lg py-2.5 text-sm font-bold ${item===subject?"bg-white text-slate-950":"text-slate-400"}`}>{item}</button>)}</div></section><section className="glass-card rounded-[26px] p-4"><p className="text-sm font-bold">今日のAIセレクト10</p><p className="mt-1 text-xs text-slate-400">教室の公開教材から {subject} を出題します。</p><div className="mt-4 grid grid-cols-2 gap-2"><button onClick={()=>choose("practice")} className="rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950">練習 <BookOpen className="ml-1 inline h-4 w-4" /></button><button onClick={()=>choose("test")} className="rounded-xl border border-white/15 py-3 text-sm font-bold text-white hover:bg-white/8">テスト <Target className="ml-1 inline h-4 w-4" /></button></div></section><section className="rounded-[26px] border border-dashed border-white/16 bg-white/[.025] p-4"><p className="text-sm font-bold">カードセットを作成</p><p className="mt-1 text-xs leading-5 text-slate-400">単語帳の範囲を指定し、用途ごとに自分だけのカードセットを作成できます。</p><button onClick={()=>toast.info("カードセット作成は、単語帳の編集画面から順次利用できます。")} className="mt-3 text-xs font-bold text-violet-200">セットを追加 <Plus className="inline h-3.5 w-3.5" /></button></section></div>;
  if(mode==="result") return <div className="px-4 pb-28 pt-8"><section className="glass-card rounded-[30px] p-6 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-amber-300/13 text-amber-200"><Trophy className="h-8 w-8" /></div><p className="eyebrow mt-5">session complete</p><h1 className="mt-2 text-2xl font-extrabold">学習を記録しました</h1><p className="mt-3 text-sm text-slate-300">覚えた：<b className="text-cyan-200">{result.known}</b>　復習：<b className="text-violet-200">{result.review}</b></p><div className="mt-6 grid grid-cols-2 gap-2"><button onClick={()=>setMode("choose")} className="rounded-xl border border-white/15 py-3 text-sm font-bold">一覧へ戻る</button><button onClick={()=>choose("practice")} className="rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950">もう一度練習</button></div></section></div>;
  if(mode==="test" && subject === "漢字") return <KanjiCanvasTest word={word} index={index} total={words.length} onAdvance={advance} onExit={()=>setMode("choose")} isSaving={isSaving}/>;
  if(mode==="test") return <div className="px-4 pb-28 pt-5"><div className="mb-4 flex items-center justify-between"><p className="eyebrow">test · {index+1} / {words.length}</p><button onClick={()=>setMode("choose")} disabled={isSaving} className="text-xs text-slate-400 disabled:opacity-50">終了する</button></div><section className="glass-card rounded-[30px] p-5"><p className="text-xs text-slate-400">次の語の意味を入力してください</p><h1 className="mt-8 text-center text-4xl font-extrabold tracking-[-.04em]">{word.front}</h1><input value={answer} disabled={isSaving} onChange={e=>setAnswer(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!isSaving)void advance(answer.trim()===word.back)}} placeholder="回答を入力" className="mt-10 w-full rounded-2xl border border-white/14 bg-slate-950/35 px-4 py-4 text-center text-lg disabled:opacity-60"/><button onClick={()=>void advance(answer.trim()===word.back)} disabled={isSaving} className="mt-3 w-full rounded-xl bg-cyan-300 py-3.5 text-sm font-bold text-slate-950 disabled:opacity-60">{isSaving?"記録を保存しています…":"答えを確認する"}</button><p className="mt-3 text-center text-[11px] text-slate-500">正解：{word.back}　（学習用の即時確認）</p></section></div>;
  return <div className="px-4 pb-28 pt-5"><div className="mb-4 flex items-center justify-between"><div><p className="eyebrow">practice · {index+1} / {words.length}</p><p className="mt-1 text-sm text-slate-300">タップで裏面を表示・左右へスワイプして回答</p></div><button onClick={()=>setMode("choose")} disabled={isSaving} className="text-xs text-slate-400 disabled:opacity-50">終了する</button></div><div className="relative mx-auto h-[370px] max-w-md"><div className="absolute inset-x-6 top-5 h-[340px] rounded-[28px] bg-white/15"/><div className="absolute inset-x-3 top-2 h-[345px] rounded-[28px] bg-white/35"/><motion.button whileTap={{scale:.985}} drag={isSaving?false:"x"} dragConstraints={{ left: 0, right: 0 }} dragElastic={.18} onDragEnd={(_, info) => { if(isSaving)return; const outcome=getSwipeOutcome(info.offset.x); if(outcome==="known")void advance(true);if(outcome==="review")void advance(false); }} onClick={()=>!isSaving&&setFlipped(!flipped)} className="absolute inset-x-0 top-0 flex h-[350px] w-full flex-col justify-between rounded-[28px] bg-[#fbfcff] p-6 text-left text-slate-950 shadow-[0_24px_48px_rgba(0,0,0,.3)] disabled:cursor-wait"><div className="flex justify-between text-[10px] font-bold uppercase tracking-widest text-slate-400"><span>{subject}</span><span>{flipped?"answer":"question"}</span></div><div className="text-center"><motion.p key={flipped?"back":"front"} initial={{opacity:0,y:5}} animate={{opacity:1,y:0}} className="text-4xl font-extrabold tracking-[-.05em]">{flipped?word.back:word.front}</motion.p>{flipped && subject==="英単語" && <button onClick={(e)=>{e.stopPropagation();window.speechSynthesis?.speak(new SpeechSynthesisUtterance(word.front))}} className="mt-4 inline-flex items-center gap-1 text-xs font-bold text-cyan-700"><Volume2 className="h-4 w-4" />発音を聞く</button>}</div><p className="text-center text-xs text-slate-400">{isSaving?"記録を保存しています…":`カードをタップして${flipped?"表面へ":"裏返す"}`}</p></motion.button></div><div className="mx-auto mt-3 grid max-w-md grid-cols-2 gap-3"><button onClick={()=>void advance(false)} disabled={isSaving} className="rounded-xl border border-violet-200/25 bg-violet-400/10 py-3.5 text-sm font-bold text-violet-100 active:scale-[.97] disabled:opacity-50"><RotateCcw className="mr-1 inline h-4 w-4" />まだ覚えていない</button><button onClick={()=>void advance(true)} disabled={isSaving} className="rounded-xl bg-cyan-300 py-3.5 text-sm font-bold text-slate-950 active:scale-[.97] disabled:opacity-60"><Check className="mr-1 inline h-4 w-4" />覚えた</button></div></div>;
}

function JournalView() { const [subject,setSubject]=useState<Subject>("英単語"); const [level,setLevel]=useState("高校1年生"); const [generating,setGenerating]=useState(false); const [article,setArticle]=useState(false); const generate = () => { setGenerating(true); window.setTimeout(()=>{setGenerating(false);setArticle(true);},900);}; return <div className="space-y-4 px-4 pb-28 pt-5"><section className="relative overflow-hidden rounded-[28px] border border-cyan-100/10 bg-gradient-to-br from-[#25356c] to-[#102342] p-5"><Sparkles className="absolute -right-2 -top-2 h-24 w-24 text-cyan-100/10"/><p className="eyebrow">reading constellation</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">StudyJournal</h1><p className="mt-2 max-w-sm text-xs leading-5 text-slate-200">話題に触れ、読む力を積み重ねる。あなたの難易度に合わせた読解を準備します。</p></section><section className="glass-card rounded-[26px] p-4"><p className="text-sm font-bold">記事の条件</p><div className="mt-4 grid grid-cols-2 rounded-xl bg-slate-950/35 p-1">{(["英単語","漢字"] as Subject[]).map(item=><button key={item} onClick={()=>setSubject(item)} className={`rounded-lg py-2.5 text-sm font-bold ${subject===item?"bg-white text-slate-950":"text-slate-400"}`}>{item}</button>)}</div><label className="mt-4 block text-xs font-bold text-slate-200">難易度<select value={level} onChange={e=>setLevel(e.target.value)} className="mt-2 w-full rounded-xl border border-white/13 bg-slate-950/35 px-3 py-3 text-sm"><option>中学生</option><option>高校1年生</option><option>高校2年生</option><option>高校3年生</option><option>大学生</option></select></label><button disabled={generating} onClick={generate} className="mt-4 w-full rounded-xl bg-cyan-300 py-3.5 text-sm font-bold text-slate-950 disabled:opacity-60">{generating ? "生成を準備しています… 約30秒" : "通常生成をはじめる"} <WandSparkles className="ml-1 inline h-4 w-4" /></button><button onClick={()=>toast.info("今日の記事は、当日公開された信頼できるニュースソースを取得できた場合のみ生成します。ニュース連携の設定後に利用できます。")} className="mt-2 w-full rounded-xl border border-white/12 py-3 text-xs font-bold text-slate-200">今日の記事を確認</button></section>{article && <section className="glass-card rounded-[26px] p-5"><p className="eyebrow">generated · 2026年8月20日</p><h2 className="mt-2 text-xl font-bold">小さな習慣がつくる集中の環境</h2><p className="mt-4 text-sm leading-8 text-slate-200">A focused learning environment does not need to be perfect. By preparing a small, repeatable routine, students can reduce the time needed to begin. A clear desk, a short timer, and one defined goal can make the next step easier.</p><div className="mt-5 border-t border-white/10 pt-4"><p className="text-sm font-bold">ミニテスト 1 / 5</p><p className="mt-2 text-sm text-slate-300">What can make the next step easier?</p><button onClick={()=>toast.success("回答を記録しました。解説は全問終了後に表示されます。")} className="mt-3 rounded-xl border border-cyan-200/25 px-3 py-2 text-xs font-bold text-cyan-200">回答する</button></div></section>}<section className="rounded-[24px] border border-dashed border-white/16 bg-white/[.025] p-4"><p className="text-sm font-bold">生成履歴</p><p className="mt-1 text-xs leading-5 text-slate-400">生成済みの記事は、日付と科目で本人の履歴に保存されます。外部AIまたはニュースの接続がない場合は、設定方法を案内します。</p></section></div> }

function AdminView() { const [tab,setTab]=useState("教室"); const tabs=["教室","利用者","単語帳","おすすめテスト","お知らせ","カレンダー"]; return <div className="space-y-4 px-4 pb-28 pt-5"><section className="glass-card rounded-[26px] p-5"><p className="eyebrow">classroom control</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">管理画面</h1><p className="mt-2 text-xs leading-5 text-slate-400">教室に公開する教材・予定・お知らせをまとめて管理します。</p></section><div className="flex gap-2 overflow-x-auto pb-1">{tabs.map(item=><button key={item} onClick={()=>setTab(item)} className={`shrink-0 rounded-xl px-3 py-2 text-xs font-bold transition ${tab===item?"bg-cyan-300 text-slate-950":"border border-white/12 bg-white/5 text-slate-300"}`}>{item}</button>)}</div><section className="glass-card rounded-[26px] p-4"><div className="flex items-start justify-between"><div><p className="text-sm font-bold">{tab}</p><p className="mt-1 text-xs text-slate-400">STAR-2026 · 自教室の管理対象</p></div><button onClick={()=>toast.success(`${tab}の作成フォームを開きました。`)} className="rounded-xl bg-cyan-300 px-3 py-2 text-xs font-bold text-slate-950"><Plus className="mr-1 inline h-3.5 w-3.5" />追加</button></div><div className="mt-5 rounded-2xl bg-slate-950/30 p-4"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-violet-300/12 text-violet-100"><ShieldCheck className="h-5 w-5" /></div><div><p className="text-sm font-bold">公開範囲を確認</p><p className="mt-1 text-xs text-slate-400">教材・お知らせ・イベントは教室または全体公開を明示します。</p></div></div><div className="mt-4 grid grid-cols-2 gap-2">{[["現在配信中","03件"],["下書き","01件"]].map(([label,value])=><div key={label} className="rounded-xl bg-white/5 p-3"><p className="text-[10px] text-slate-400">{label}</p><p className="mt-1 text-lg font-bold">{value}</p></div>)}</div></div><button onClick={()=>toast.info("先生は自教室の生徒のみを管理できます。全体管理者は教室を横断して絞り込みできます。")} className="mt-4 text-xs font-bold text-cyan-200">権限の説明を見る <ArrowRight className="inline h-3.5 w-3.5" /></button></section><section className="rounded-[24px] border border-dashed border-white/16 bg-white/[.025] p-4"><p className="text-sm font-bold">モンスター管理</p><p className="mt-1 text-xs leading-5 text-slate-400">成長段階ごとの画像は外部ストレージに登録し、URLとメタデータのみを保存します。</p><button onClick={()=>toast.info("画像登録はストレージ連携の設定後に有効になります。")} className="mt-3 text-xs font-bold text-violet-200">画像を管理 <ArrowRight className="inline h-3.5 w-3.5" /></button></section></div> }

function JournalWorkspace() {
  type Entry = { id: string; subject: Subject; level: string; title: string; body: string; createdAt: string; questions: Array<{ question: string; answer: string; explanation: string }>; source?: { title: string; url: string; domain: string } | null };
  const [subject, setSubject] = useState<Subject>("英単語");
  const [level, setLevel] = useState("高校1年生");
  const [historySubject, setHistorySubject] = useState<"all" | "english" | "kanji">("all");
  const [current, setCurrent] = useState<Entry | null>(null);
  const [revealed, setRevealed] = useState<number | null>(null);
  const historyInput = useMemo(() => historySubject === "all" ? undefined : { subject: historySubject }, [historySubject]);
  const history = trpc.journal.list.useQuery(historyInput, { retry: false });
  const generateMutation = trpc.journal.generate.useMutation();
  const entries: Entry[] = (history.data ?? []).map(item => ({ id: String(item.id), subject: item.subject === "english" ? "英単語" : "漢字", level: item.difficulty, title: item.articleTitle, body: item.articleBody, createdAt: new Date(item.createdAt).toLocaleDateString("ja-JP"), questions: item.questions, source: item.sourceUrl && item.sourceTitle ? { title: item.sourceTitle, url: item.sourceUrl, domain: new URL(item.sourceUrl).hostname } : null }));
  const generate = async (mode: "normal" | "today") => { try { const article = await generateMutation.mutateAsync({ subject: subject === "英単語" ? "english" : "kanji", difficulty: level, mode }); setCurrent({ id: String(article.id ?? crypto.randomUUID()), subject, level, title: article.title, body: article.body, createdAt: new Date().toLocaleDateString("ja-JP"), questions: article.questions, source: article.source }); setRevealed(null); await history.refetch(); toast.success("記事と3問のミニテストを保存しました。"); } catch (error) { toast.error(error instanceof Error ? error.message : "記事を生成できませんでした。再試行してください。"); } };
  return <div className="space-y-4 px-4 pb-28 pt-5">
    <section className="relative overflow-hidden rounded-[28px] border border-cyan-100/10 bg-gradient-to-br from-[#25356c] to-[#102342] p-5"><Sparkles className="absolute -right-2 -top-2 h-24 w-24 text-cyan-100/10"/><p className="eyebrow">reading constellation</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">StudyJournal</h1><p className="mt-2 max-w-sm text-xs leading-5 text-slate-200">AIが生成した読解を保存し、ニュースを題材にする場合は出典リンクを残します。</p></section>
    <section className="glass-card rounded-[26px] p-4"><p className="text-sm font-bold">記事の条件</p><div className="mt-4 grid grid-cols-2 rounded-xl bg-slate-950/35 p-1">{(["英単語", "漢字"] as Subject[]).map(item => <button key={item} onClick={() => setSubject(item)} className={`rounded-lg py-2.5 text-sm font-bold ${subject === item ? "bg-white text-slate-950" : "text-slate-400"}`}>{item}</button>)}</div><label className="mt-4 block text-xs font-bold text-slate-200">難易度<select value={level} onChange={event => setLevel(event.target.value)} className="mt-2 w-full rounded-xl border border-white/13 bg-slate-950/35 px-3 py-3 text-sm"><option>中学生</option><option>高校1年生</option><option>高校2年生</option><option>高校3年生</option><option>大学生</option></select></label><button disabled={generateMutation.isPending} onClick={() => void generate("normal")} className="mt-4 w-full rounded-xl bg-cyan-300 py-3.5 text-sm font-bold text-slate-950 disabled:opacity-60">{generateMutation.isPending ? "生成しています…" : "通常生成をはじめる"} <WandSparkles className="ml-1 inline h-4 w-4"/></button><button disabled={generateMutation.isPending} onClick={() => void generate("today")} className="mt-2 w-full rounded-xl border border-white/12 py-3 text-xs font-bold text-slate-200 disabled:opacity-60">今日のニュースを題材に生成</button><p className="mt-3 text-[10px] leading-4 text-slate-500">ニュース題材は見出しと出典URLを保存し、本文の転載は行いません。</p></section>
    {current && <section className="glass-card rounded-[26px] p-5"><p className="eyebrow">generated · {current.createdAt} · {current.level}</p><h2 className="mt-2 text-xl font-bold">{current.title}</h2>{current.source && <a href={current.source.url} target="_blank" rel="noreferrer" className="mt-3 inline-flex max-w-full items-center gap-1 text-xs font-bold text-cyan-200 hover:underline">出典：{current.source.domain} <ArrowRight className="h-3.5 w-3.5"/></a>}<p className="mt-4 whitespace-pre-line text-sm leading-8 text-slate-200">{current.body}</p><div className="mt-5 space-y-3 border-t border-white/10 pt-4"><p className="text-sm font-bold">ミニテスト {current.questions.length}問</p>{current.questions.map((question, index) => <div key={question.question} className="rounded-xl bg-slate-950/25 p-3"><p className="text-sm text-slate-200">{index + 1}. {question.question}</p>{revealed === index ? <div className="mt-3 text-xs leading-5 text-slate-300"><p><b className="text-cyan-200">答え：</b>{question.answer}</p><p className="mt-1 text-slate-400">{question.explanation}</p></div> : <button onClick={() => setRevealed(index)} className="mt-3 rounded-xl border border-cyan-200/25 px-3 py-2 text-xs font-bold text-cyan-200">答えと解説を見る</button>}</div>)}</div></section>}
    <section className="glass-card rounded-[24px] p-4"><div className="flex items-center justify-between"><p className="text-sm font-bold">生成履歴</p><span className="font-mono text-[10px] text-slate-400">{entries.length}件</span></div><div className="mt-3 grid grid-cols-3 rounded-xl bg-slate-950/35 p-1">{([['all', 'すべて'], ['english', '英単語'], ['kanji', '漢字']] as const).map(([value, label]) => <button key={value} onClick={() => { setHistorySubject(value); setCurrent(null); setRevealed(null); }} className={`rounded-lg py-2 text-xs font-bold ${historySubject === value ? "bg-violet-200 text-slate-950" : "text-slate-400"}`}>{label}</button>)}</div><div className="mt-3 space-y-2">{history.isLoading ? <p className="text-xs text-slate-400">履歴を読み込んでいます…</p> : entries.length ? entries.map(entry => <button key={entry.id} onClick={() => { setCurrent(entry); setRevealed(null); }} className={`flex w-full items-center gap-3 rounded-xl p-3 text-left ${current?.id === entry.id ? "bg-cyan-300/10" : "bg-slate-950/25 hover:bg-white/6"}`}><NotebookPen className="h-4 w-4 text-cyan-200"/><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{entry.title}</span><span className="mt-1 block text-[11px] text-slate-400">{entry.createdAt} · {entry.subject} · {entry.level}</span></span><ChevronDown className="h-4 w-4 -rotate-90 text-slate-500"/></button>) : <p className="rounded-xl bg-slate-950/25 p-3 text-xs leading-5 text-slate-400">この科目の生成履歴はまだありません。</p>}</div></section>
  </div>;
}

function PinReissuePanel() {
  const members=trpc.classroom.members.list.useQuery(undefined,{retry:false}); const reset=trpc.classroom.members.resetPin.useMutation(); const [profileId,setProfileId]=useState(""); const [pin,setPin]=useState("");
  const submit=async(event:React.FormEvent)=>{event.preventDefault();if(!profileId)return toast.error("再発行する利用者を選択してください。");if(!/^\d{4}$/.test(pin))return toast.error("PINは4桁の数字で入力してください。");try{await reset.mutateAsync({profileId:Number(profileId),pin});setPin("");toast.success("PINを再発行し、既存のログインを失効しました。");}catch(error){toast.error(error instanceof Error?error.message:"PINを再発行できませんでした。");}};
  if(members.isLoading)return <section className="glass-card rounded-[24px] p-4"><p className="text-xs text-slate-400">PIN再発行の対象を読み込んでいます…</p></section>;
  if(members.isError)return <section className="rounded-[24px] border border-white/12 bg-white/[.025] p-4"><p className="text-sm font-bold">PINの再発行</p><p className="mt-1 text-xs leading-5 text-slate-400">PINの再発行は、所属教室の先生または教室管理者のみが行えます。</p></section>;
  return <section className="glass-card rounded-[24px] p-4"><p className="text-sm font-bold">PINの再発行</p><p className="mt-1 text-xs leading-5 text-slate-400">再発行すると、対象利用者の既存PINセッションは失効します。新しいPINは安全な経路で共有してください。</p><form onSubmit={submit} className="mt-4 grid gap-2 sm:grid-cols-2"><label className="text-xs font-bold text-slate-200">対象利用者<select value={profileId} onChange={event=>setProfileId(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"><option value="">選択してください</option>{(members.data??[]).map(member=><option key={member.id} value={member.id}>{member.displayName??`利用者 #${member.id}`} · {member.classroomRole}</option>)}</select></label><label className="text-xs font-bold text-slate-200">新しい4桁PIN<input inputMode="numeric" maxLength={4} value={pin} onChange={event=>setPin(event.target.value.replace(/\D/g,""))} placeholder="••••" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-center font-mono text-lg tracking-[.4em]"/></label><button disabled={reset.isPending} className="sm:col-span-2 rounded-xl border border-violet-200/30 bg-violet-300/10 py-3 text-sm font-bold text-violet-100 disabled:opacity-60">{reset.isPending?"再発行しています…":"PINを再発行"}</button></form></section>;
}

function ManagementInsights() {
  const insights=trpc.management.insights.useQuery(undefined,{retry:false,staleTime:30_000});
  if(insights.isLoading)return <section className="glass-card rounded-[24px] p-4"><p className="text-xs text-slate-400">学習・管理記録を集計しています…</p></section>;
  if(insights.isError||!insights.data)return <section className="rounded-[24px] border border-red-200/20 bg-red-400/5 p-4" role="alert"><p className="text-sm font-bold text-red-100">教室の記録を取得できませんでした</p><p className="mt-1 text-xs leading-5 text-slate-300">{insights.error?.message??"通信状況または管理権限を確認して、もう一度お試しください。"}</p><button onClick={()=>void insights.refetch()} disabled={insights.isFetching} className="mt-3 rounded-xl border border-red-200/30 px-3 py-2 text-xs font-bold text-red-100 disabled:opacity-60">{insights.isFetching?"再取得しています…":"再試行"}</button></section>;
  const data=insights.data; const focusMinutes=Math.floor(data.totalFocusSeconds/60);
  return <section className="glass-card rounded-[26px] p-4"><div className="flex items-center justify-between"><div><p className="eyebrow">record observatory</p><h2 className="mt-1 text-lg font-bold">教室の記録</h2></div><span className="rounded-full bg-cyan-300/10 px-2.5 py-1 text-[10px] font-bold text-cyan-100">実データ</span></div><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4">{[["利用者",`${data.memberCount}人`],["学習時間",`${focusMinutes}分`],["正答率",`${data.retention}%`],["Journal",`${data.journalCount}件`]].map(([label,value])=><div key={label} className="rounded-2xl bg-slate-950/30 p-3"><p className="text-[10px] text-slate-400">{label}</p><p className="mt-1 text-lg font-bold">{value}</p></div>)}</div><div className="mt-4"><p className="text-xs font-bold text-slate-200">最近の操作・学習記録</p><div className="mt-2 max-h-44 space-y-2 overflow-y-auto pr-1">{data.recentActivities.length?data.recentActivities.map(item=><div key={item.id} className="rounded-xl bg-white/[.035] px-3 py-2"><p className="text-xs font-semibold text-slate-100">{item.action}</p><p className="mt-1 text-[10px] text-slate-400">{item.classroomName}・{item.actorName} {item.details?`・${item.details}`:""}</p></div>):<p className="rounded-xl bg-white/[.035] p-3 text-xs text-slate-400">まだ記録がありません。教室作成、PIN参加、集中完了、Journal生成がここに残ります。</p>}</div></div></section>;
}

function AdminWorkspace({ teacherSession }: { teacherSession: { id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string } | null }) {
  return <><div className="px-4 pt-5"><ManagementInsights/></div><LegacyAdminWorkspace teacherSession={teacherSession}/></>;
}

function LegacyAdminWorkspace({ teacherSession }: { teacherSession: { classroomId: number; classroomName: string; classroomCode: string } | null }) {
  const tabs=teacherSession?["利用者","単語帳","おすすめテスト","お知らせ","カレンダー"]:["教室","利用者","単語帳","おすすめテスト","お知らせ","カレンダー"]; const fields:Record<string,string[]>={"利用者":["表示名","PIN再設定対象","権限"],"単語帳":["単語帳名","科目","公開範囲"],"おすすめテスト":["科目","単語帳・範囲","問題数","配信期間"],"お知らせ":["タイトル","本文","公開範囲"],"カレンダー":["イベント名","開始日時","終了日時","公開範囲"]}; const [tab,setTab]=useState(tabs[0]); const [items,setItems]=useState<Record<string,string[]>>({"利用者":["学習者｜PIN: 再設定可｜student"],"単語帳":["2026 標準単語帳 1｜英語｜教室公開"],"おすすめテスト":["英語｜第1章｜10問｜8/20–8/31"],"お知らせ":["新しい学習ミッション｜本日公開｜教室公開"],"カレンダー":["読解ワークショップ｜8/24 10:00｜8/24 11:00｜教室公開"]}); const [form,setForm]=useState<Record<string,string>>({}); const [editing,setEditing]=useState<number|null>(null); const [roomForm,setRoomForm]=useState({name:"",code:"",teacherUserId:""}); const [editingRoom,setEditingRoom]=useState<number|null>(null); const active=fields[tab] ?? [];
  const utils=trpc.useUtils(); const rooms=trpc.classroom.rooms.list.useQuery(undefined,{retry:false}); const createRoom=trpc.classroom.rooms.create.useMutation(); const updateRoom=trpc.classroom.rooms.update.useMutation();
  const reset=()=>{setForm({});setEditing(null);}; const submit=()=>{const values=active.map(field=>form[field]?.trim()??"");if(values.some(value=>!value))return toast.error("すべての必須項目を入力してください。");const item=values.join("｜");setItems(current=>({...current,[tab]:editing===null?[...current[tab],item]:current[tab].map((candidate,index)=>index===editing?item:candidate)}));toast.success(editing===null?`${tab}を追加しました。`:`${tab}を更新しました。`);reset();}; const edit=(item:string,index:number)=>{const values=item.split("｜");setForm(Object.fromEntries(active.map((field,candidate)=>[field,values[candidate]??""])));setEditing(index);}; const resetRoom=()=>{setRoomForm({name:"",code:"",teacherUserId:""});setEditingRoom(null);};
  const submitRoom=async(event:React.FormEvent)=>{event.preventDefault();const name=roomForm.name.trim();const code=roomForm.code.trim().toUpperCase();if(!name)return toast.error("教室名を入力してください。");if(!/^[A-Z0-9-]{3,32}$/.test(code))return toast.error("教室コードは英数字とハイフンで3〜32文字にしてください。");const teacherUserId=roomForm.teacherUserId.trim()?Number(roomForm.teacherUserId):undefined;if(roomForm.teacherUserId.trim()&&(!Number.isInteger(teacherUserId)||teacherUserId!<=0))return toast.error("担当先生IDは正の整数で入力してください。");try{if(editingRoom===null)await createRoom.mutateAsync({name,code,teacherUserId});else await updateRoom.mutateAsync({classroomId:editingRoom,name,teacherUserId:teacherUserId??null});await utils.classroom.rooms.list.invalidate();toast.success(editingRoom===null?"教室を保存しました。":"教室情報を更新しました。");resetRoom();}catch(error){toast.error(error instanceof Error?error.message:"教室を保存できませんでした。");}};
  const header=<><section className="glass-card rounded-[26px] p-5"><p className="eyebrow">classroom control</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.05em]">{teacherSession?"先生管理画面":"管理画面"}</h1><p className="mt-2 text-xs leading-5 text-slate-400">{teacherSession?`${teacherSession.classroomName}（${teacherSession.classroomCode}）の利用者・教材・配信だけを管理します。`:"教室に公開する教材・予定・お知らせを、対象を確認しながら管理します。"}</p></section><div className="flex gap-2 overflow-x-auto pb-1">{tabs.map(item=><button key={item} onClick={()=>{setTab(item);reset();resetRoom();}} className={`shrink-0 rounded-xl px-3 py-2 text-xs font-bold transition ${tab===item?"bg-cyan-300 text-slate-950":"border border-white/12 bg-white/5 text-slate-300"}`}>{item}</button>)}</div></>;
  if(tab==="教室")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<section className="glass-card rounded-[26px] p-4"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-violet-300/12 text-violet-100"><ShieldCheck className="h-5 w-5"/></div><div><p className="text-sm font-bold">教室を保存</p><p className="mt-1 text-xs text-slate-400">作成・編集内容はサーバーへ保存され、次回も表示されます。</p></div></div><div className="mt-5 space-y-2">{rooms.isLoading&&<p className="rounded-xl bg-slate-950/30 p-3 text-xs text-slate-400">教室を読み込んでいます…</p>}{rooms.isError&&<p className="rounded-xl bg-red-400/10 p-3 text-xs text-red-100">教室を取得できませんでした。再読み込みしてください。</p>}{(rooms.data??[]).map(room=><div key={room.id} className="flex items-center gap-2 rounded-xl bg-slate-950/30 p-3"><span className="min-w-0 flex-1 text-sm">{room.name}｜{room.code}{room.teacherUserId?`｜先生ID: ${room.teacherUserId}`:""}</span><button onClick={()=>{setEditingRoom(room.id);setRoomForm({name:room.name,code:room.code,teacherUserId:room.teacherUserId?String(room.teacherUserId):""});}} className="text-violet-200" aria-label="教室を編集"><Settings2 className="h-4 w-4"/></button></div>)}</div><form onSubmit={submitRoom} className="mt-4 grid gap-2 sm:grid-cols-2"><label className="text-xs font-bold text-slate-200">教室名<input required value={roomForm.name} onChange={event=>setRoomForm(current=>({...current,name:event.target.value}))} placeholder="教室名" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"/></label><label className="text-xs font-bold text-slate-200">教室コード<input required disabled={editingRoom!==null} value={roomForm.code} onChange={event=>setRoomForm(current=>({...current,code:event.target.value.toUpperCase()}))} placeholder="例：STAR-2026" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm disabled:opacity-50"/></label><label className="text-xs font-bold text-slate-200 sm:col-span-2">担当先生ID（任意）<input inputMode="numeric" value={roomForm.teacherUserId} onChange={event=>setRoomForm(current=>({...current,teacherUserId:event.target.value.replace(/\D/g,"")}))} placeholder="担当先生ID" className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"/></label><button disabled={createRoom.isPending||updateRoom.isPending} className="rounded-xl bg-cyan-300 py-3 text-xs font-bold text-slate-950 disabled:opacity-60">{editingRoom===null?"追加して保存":"更新して保存"}</button><button type="button" onClick={resetRoom} className="rounded-xl border border-white/12 py-3 text-xs font-bold text-slate-200">入力を取り消す</button></form></section></div>;
  if(tab==="利用者")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<ClassroomMembersPanel/><PinReissuePanel/></div>;
  if(tab==="単語帳")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<ClassroomContentManager section="wordbooks"/></div>;
  if(tab==="おすすめテスト")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<RecommendedTestManager/></div>;
  if(tab==="お知らせ")return <div className="space-y-4 px-4 pb-28 pt-5">{header}<ClassroomContentManager section="announcements"/><AnnouncementHistoryPanel/></div>;
  return <div className="space-y-4 px-4 pb-28 pt-5">{header}<section className="glass-card rounded-[26px] p-4"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-violet-300/12 text-violet-100"><ShieldCheck className="h-5 w-5"/></div><div><p className="text-sm font-bold">{tab}を管理</p><p className="mt-1 text-xs text-slate-400">公開範囲と対象を確認して保存します。</p></div></div><div className="mt-5 space-y-2">{items[tab].map((item,index)=><div key={`${item}-${index}`} className="flex items-center gap-2 rounded-xl bg-slate-950/30 p-3"><span className="min-w-0 flex-1 text-sm">{item}</span><button onClick={()=>edit(item,index)} className="text-violet-200" aria-label="編集"><Settings2 className="h-4 w-4"/></button><button onClick={()=>setItems(current=>({...current,[tab]:current[tab].filter((_,candidate)=>candidate!==index)}))} className="text-red-200" aria-label="削除"><X className="h-4 w-4"/></button></div>)}</div><div className="mt-4 grid gap-2 sm:grid-cols-2">{active.map(field=><label key={field} className="text-xs font-bold text-slate-200">{field}<input value={form[field]??""} onChange={event=>setForm(current=>({...current,[field]:event.target.value}))} placeholder={field} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm"/></label>)}</div><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={submit} className="rounded-xl bg-cyan-300 py-3 text-xs font-bold text-slate-950">{editing===null?"追加して保存":"更新して保存"}</button><button onClick={reset} className="rounded-xl border border-white/12 py-3 text-xs font-bold text-slate-200">入力を取り消す</button></div></section>{tab==="利用者"&&<PinReissuePanel/>}<section className="rounded-[24px] border border-dashed border-white/16 bg-white/[.025] p-4"><p className="text-sm font-bold">公開範囲と権限</p><p className="mt-1 text-xs leading-5 text-slate-400">先生は自教室の配信を管理し、全体管理者は全教室を絞り込みます。本番接続時はサーバー側でこの範囲を検証します。</p></section></div>;
}

function ProfileSheet({ onClose, onLogout }: { onClose: () => void; onLogout: () => void }) { return <div className="fixed inset-0 z-50 bg-slate-950/65" onClick={onClose}><motion.aside initial={{x:"100%"}} animate={{x:0}} exit={{x:"100%"}} transition={{duration:.22}} onClick={e=>e.stopPropagation()} className="absolute right-0 top-0 h-full w-[min(340px,90vw)] border-l border-white/10 bg-[#0d1831] p-5 shadow-2xl"><div className="flex justify-between"><div><p className="eyebrow">profile</p><h2 className="mt-1 text-xl font-bold">学習プロフィール</h2></div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl bg-white/8"><X className="h-4 w-4" /></button></div><div className="mt-6 flex items-center gap-3 rounded-2xl bg-white/5 p-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-gradient-to-br from-violet-300 to-cyan-200 text-slate-950"><UserRound className="h-5 w-5" /></div><div><p className="font-bold">学習者</p><p className="mt-1 text-xs text-slate-400">STAR-2026</p></div></div><div className="mt-5 space-y-2">{[[GraduationCap,"所属教室","STAR-2026"],[KeyRound,"PIN","••••"],[LibraryBig,"持ち物","卵 1・復活チケット 2"],[Settings2,"設定","演出・タイマー・表示"]].map(([Icon,label,value]) => { const I=Icon as typeof GraduationCap; return <button key={label as string} onClick={()=>toast.info(`${label}の設定画面を準備しています。`)} className="flex w-full items-center gap-3 rounded-xl p-3 text-left transition hover:bg-white/6"><I className="h-4 w-4 text-cyan-200"/><span className="flex-1 text-sm font-semibold">{label as string}</span><span className="text-xs text-slate-400">{value as string}</span></button>})}</div><button onClick={onLogout} className="mt-7 flex w-full items-center justify-center gap-2 rounded-xl border border-red-200/20 bg-red-400/5 py-3 text-sm font-bold text-red-100"><LogOut className="h-4 w-4" />ログアウト</button></motion.aside></div> }

export default function Home() {
  const preview = new URLSearchParams(window.location.search).get("preview"); const [entered,setEntered]=useState(() => ["home","journal","admin"].includes(preview ?? "")); const [page,setPage]=useState<NavKey>(() => preview === "journal" ? "journal" : preview === "admin" ? "admin" : "home"); const [profile,setProfile]=useState(false); const [books,setBooks]=useState(initialBooks); const [running,setRunning]=useState(false); const [elapsed,setElapsed]=useState(0); const [timerStartedAt,setTimerStartedAt]=useState<Date|null>(null); const [previousPage,setPreviousPage]=useState<NavKey>("home"); const [teacherView,setTeacherView]=useState<{ id: number; name: string | null; classroomId: number; classroomName: string; classroomCode: string } | null>(null);
  const pinLogin = trpc.auth.pinLogin.useMutation(); const pinLogout = trpc.auth.pinLogout.useMutation(); const siteAdminLogout = trpc.siteAdmin.logout.useMutation(); const teacherAdminLogout = trpc.teacherAdmin.logout.useMutation(); const pinSession = trpc.auth.pinMe.useQuery(undefined,{retry:false,staleTime:60_000}); const siteAdminSession = trpc.siteAdmin.me.useQuery(undefined,{retry:false,staleTime:60_000}); const teacherAdminSession = trpc.teacherAdmin.me.useQuery(undefined,{retry:false,staleTime:60_000}); const learningSummary=trpc.learning.summary.useQuery(undefined,{retry:false,staleTime:30_000}); const saveFocus=trpc.learning.saveFocusSession.useMutation(); const utils=trpc.useUtils();
  useEffect(()=>{ if(pinSession.data)setEntered(true); },[pinSession.data]);
  useEffect(()=>{ if(siteAdminSession.data){setEntered(true);setPage("admin");} },[siteAdminSession.data]);
  useEffect(()=>{ if(teacherAdminSession.data){setTeacherView(teacherAdminSession.data.teacher);setEntered(true);setPage("admin");} },[teacherAdminSession.data]);
  useEffect(()=>{ if(!running)return; const id=window.setInterval(()=>setElapsed(s=>s+1),1000); return()=>window.clearInterval(id);},[running]);
  const enter=async(pin:string,classroom:string)=>{try{await pinLogin.mutateAsync({pin,classroomCode:classroom});setEntered(true);toast.success("学習空間を開きました。");}catch(error){toast.error(error instanceof Error?error.message:"認証できませんでした。もう一度お試しください。");throw error;}};
  const move=(next:NavKey)=>{if(next!==page){setPreviousPage(page);setPage(next);}}; const toggleTimer=()=>{if(!running){setTimerStartedAt(new Date(Date.now()-elapsed*1000));setRunning(true);return;}setRunning(false);if(elapsed<1)return;const completedAt=new Date();void saveFocus.mutateAsync({startedAt:timerStartedAt??new Date(completedAt.getTime()-elapsed*1000),completedAt,focusSeconds:elapsed}).then(async()=>{await utils.learning.summary.invalidate();toast.success(`${Math.floor(elapsed/60)}分の集中記録を保存しました。`);setElapsed(0);setTimerStartedAt(null);}).catch(()=>toast.error("集中記録を保存できませんでした。"));};
  if(!entered)return <LoginGate onEnter={enter} onTeacherEnter={teacher=>{setTeacherView(teacher);setEntered(true);setPage("admin");}}/>;
  const activeTeacher = teacherAdminSession.data?.teacher ?? teacherView;
  const title:Record<NavKey,string>={home:"StudyVerse",books:"単語帳",cards:"単語カード",admin:activeTeacher?"先生管理画面":"管理画面",journal:"StudyJournal"};
  return <div className="sky-shell app-scroll min-h-screen"><div className="star-field opacity-40" />{running && <div className="fixed inset-x-0 top-0 z-50 h-1 bg-cyan-300 shadow-[0_0_14px_#71efe0]"/>}<div className="relative mx-auto min-h-screen max-w-5xl"><Header page={title[page]} onBack={()=>setPage(previousPage)} onProfile={()=>setProfile(true)}/><AnimatePresence mode="wait"><motion.main key={page} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-6}} transition={{duration:.18}}>{page==="home"&&<HomeView setPage={move} running={running} elapsed={elapsed} onToggleTimer={toggleTimer} onResetTimer={()=>{setRunning(false);setElapsed(0);setTimerStartedAt(null);}} summary={learningSummary.data}/>} {page==="books"&&<BooksView books={books} setBooks={setBooks} setPage={move}/>} {page==="cards"&&<CardsWorkspace books={books}/>} {page==="journal"&&<JournalWorkspace/>} {page==="admin"&&<AdminWorkspace teacherSession={activeTeacher}/>}</motion.main></AnimatePresence><nav className="nav-safe fixed inset-x-0 bottom-0 z-30 border-t border-white/[.08] bg-[#080e21]/90 px-3 pt-2 backdrop-blur-xl"><div className="mx-auto grid max-w-lg grid-cols-4">{navItems.map(item=>{const Icon=item.icon;const active=page===item.key;return <button key={item.key} onClick={()=>move(item.key)} className={`relative flex flex-col items-center gap-1 py-2 text-[10px] font-semibold transition ${active?"text-cyan-200":"text-slate-500 hover:text-slate-300"}`}>{active&&<i className="absolute top-0 h-0.5 w-6 rounded-full bg-cyan-200"/>}<Icon className="h-[18px] w-[18px]"/>{item.label}</button>})}</div></nav>{profile&&<ProfileSheet onClose={()=>setProfile(false)} onLogout={()=>{void Promise.allSettled([pinLogout.mutateAsync(),siteAdminLogout.mutateAsync(),teacherAdminLogout.mutateAsync()]).finally(()=>{setTeacherView(null);setEntered(false);setProfile(false);setPage("home");toast.info("ログアウトしました。");});}}/>}</div></div>;
}
